using System;
using System.Drawing;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Threading;
using System.Windows.Forms;
using Microsoft.Win32;

internal static class Setup {
 const string Version="0.1.0";
 static string[] Payload={"LilyTools.exe","LilyTools.exe.config","LICENSE","NOTICE","README.md","PRIVACY.md"};
 static string DefaultDir=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Programs","LilyTools");
 static string Option(string[] args,string flag){int i=Array.IndexOf(args,flag);return i>=0&&i+1<args.Length?args[i+1]:null;}
 static string Validate(string path){string full=Path.GetFullPath(path).TrimEnd(Path.DirectorySeparatorChar);string parent=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Programs");string name=Path.GetFileName(full);if(!string.Equals(Path.GetDirectoryName(full),parent,StringComparison.OrdinalIgnoreCase)||(name!="LilyTools"&&!name.StartsWith("LilyTools-InstallTest-",StringComparison.Ordinal)))throw new InvalidOperationException("Unsupported installation directory.");return full;}
 static string Key(string target){return @"Software\Microsoft\Windows\CurrentVersion\Uninstall\"+Path.GetFileName(target);}
 static bool IsTest(string target){return Path.GetFileName(target).StartsWith("LilyTools-InstallTest-",StringComparison.Ordinal);}
 static void WriteResource(string resource,string target){using(var input=Assembly.GetExecutingAssembly().GetManifestResourceStream("payload."+resource)){if(input==null)throw new IOException("Missing embedded file: "+resource);using(var output=File.Create(target))input.CopyTo(output);}}
 static void Shortcut(string path,string target,string arguments){Type t=Type.GetTypeFromProgID("WScript.Shell");dynamic shell=Activator.CreateInstance(t);dynamic link=shell.CreateShortcut(path);link.TargetPath=target;link.Arguments=arguments;link.WorkingDirectory=Path.GetDirectoryName(target);link.Description="LilyTools";link.Save();}
 static void Install(string target,bool desktop,bool shortcuts,bool start){target=Validate(target);foreach(var process in Process.GetProcessesByName("LilyTools")){try{if(string.Equals(process.MainModule.FileName,Path.Combine(target,"LilyTools.exe"),StringComparison.OrdinalIgnoreCase))throw new IOException("LilyTools 正在运行，请从托盘退出后重试。");}catch(System.ComponentModel.Win32Exception){}}
  Directory.CreateDirectory(target);foreach(string file in Payload)WriteResource(file,Path.Combine(target,file));File.Copy(Assembly.GetExecutingAssembly().Location,Path.Combine(target,"Uninstall.exe"),true);
  if(shortcuts&&!IsTest(target)){string menu=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Programs),"LilyTools");Directory.CreateDirectory(menu);Shortcut(Path.Combine(menu,"LilyTools.lnk"),Path.Combine(target,"LilyTools.exe"),"");Shortcut(Path.Combine(menu,"卸载 LilyTools.lnk"),Path.Combine(target,"Uninstall.exe"),"--uninstall");if(desktop)Shortcut(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory),"LilyTools.lnk"),Path.Combine(target,"LilyTools.exe"),"");}
  using(var key=Registry.CurrentUser.CreateSubKey(Key(target))){key.SetValue("DisplayName","LilyTools"+(IsTest(target)?" Installation Test":""));key.SetValue("DisplayVersion",Version);key.SetValue("Publisher","LilyTools contributors");key.SetValue("InstallLocation",target);key.SetValue("DisplayIcon",Path.Combine(target,"LilyTools.exe"));key.SetValue("UninstallString","\""+Path.Combine(target,"Uninstall.exe")+"\" --uninstall");key.SetValue("QuietUninstallString","\""+Path.Combine(target,"Uninstall.exe")+"\" --uninstall --silent");key.SetValue("NoModify",1);key.SetValue("NoRepair",1);}
  if(start)Process.Start(new ProcessStartInfo(Path.Combine(target,"LilyTools.exe")){UseShellExecute=true});
 }
 static void DeleteFile(string file){for(int i=0;i<30;i++){try{if(File.Exists(file))File.Delete(file);return;}catch(IOException){Thread.Sleep(100);}}throw new IOException("文件仍被占用，请退出 LilyTools 后重试："+file);}
 static void Uninstall(string target){target=Validate(target);foreach(var process in Process.GetProcessesByName("LilyTools"))try{if(string.Equals(process.MainModule.FileName,Path.Combine(target,"LilyTools.exe"),StringComparison.OrdinalIgnoreCase))process.Kill();}catch(System.ComponentModel.Win32Exception){}
  foreach(string file in Payload.Concat(new[]{"Uninstall.exe"}))DeleteFile(Path.Combine(target,file));if(Directory.Exists(target)&&!Directory.EnumerateFileSystemEntries(target).Any())Directory.Delete(target);
  if(!IsTest(target)){string menu=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Programs),"LilyTools");DeleteFile(Path.Combine(menu,"LilyTools.lnk"));DeleteFile(Path.Combine(menu,"卸载 LilyTools.lnk"));if(Directory.Exists(menu)&&!Directory.EnumerateFileSystemEntries(menu).Any())Directory.Delete(menu);string desktop=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory),"LilyTools.lnk");if(File.Exists(desktop)){Type t=Type.GetTypeFromProgID("WScript.Shell");dynamic shell=Activator.CreateInstance(t);dynamic link=shell.CreateShortcut(desktop);if(string.Equals((string)link.TargetPath,Path.Combine(target,"LilyTools.exe"),StringComparison.OrdinalIgnoreCase))DeleteFile(desktop);}}
  Registry.CurrentUser.DeleteSubKeyTree(Key(target),false);
 }
 [STAThread] static int Main(string[] args){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);bool silent=args.Contains("--silent");try{if(args.Contains("--uninstall")){string target=Validate(Option(args,"--target")??Path.GetDirectoryName(Assembly.GetExecutingAssembly().Location));if(!silent&&MessageBox.Show("卸载 LilyTools？\n剪贴板历史和设置会保留在本机数据目录。","卸载",MessageBoxButtons.YesNo)!=DialogResult.Yes)return 0;if(Option(args,"--target")==null){string copy=Path.Combine(Path.GetTempPath(),"LilyTools-Uninstall-"+Guid.NewGuid()+".exe");File.Copy(Assembly.GetExecutingAssembly().Location,copy);Process.Start(new ProcessStartInfo(copy,"--uninstall --silent --target \""+target+"\""){UseShellExecute=false,CreateNoWindow=true});return 0;}Uninstall(target);return 0;}
  string destination=Validate(Option(args,"--directory")??DefaultDir);if(silent){Install(destination,!args.Contains("--no-desktop"),!args.Contains("--no-shortcuts"),!args.Contains("--no-start"));return 0;}
  using(var form=new Form{Text="安装 LilyTools",ClientSize=new Size(520,310),StartPosition=FormStartPosition.CenterScreen,FormBorderStyle=FormBorderStyle.FixedDialog,MaximizeBox=false,Font=new Font("Microsoft YaHei UI",10),BackColor=Color.White}){var title=new Label{Text="LilyTools",Font=new Font("Microsoft YaHei UI",23),Location=new Point(26,20),AutoSize=true};var info=new Label{Text="统一搜索 · 本地剪贴板 · 内容识别\n\n非商业用途免费 · 不含广告\n安装到当前用户目录，无需管理员权限。",Location=new Point(28,75),Size=new Size(455,95)};var desk=new CheckBox{Text="创建桌面快捷方式",Checked=true,Location=new Point(28,174),AutoSize=true};var agree=new Label{Text="点击安装即同意 PolyForm Noncommercial 1.0.0 许可。",Location=new Point(28,208),AutoSize=true,ForeColor=Color.DimGray};var button=new Button{Text="一键安装",Location=new Point(340,249),Size=new Size(150,40),FlatStyle=FlatStyle.Flat,BackColor=Color.FromArgb(83,96,225),ForeColor=Color.White};button.Click+=(s,e)=>{button.Enabled=false;try{Install(destination,desk.Checked,true,true);MessageBox.Show("安装完成。\nAlt+空格搜索，Ctrl+Shift+V 查看剪贴板。","LilyTools");form.Close();}catch(Exception ex){MessageBox.Show(ex.Message,"安装失败");button.Enabled=true;}};form.Controls.AddRange(new Control[]{title,info,desk,agree,button});Application.Run(form);}return 0;
 }catch(Exception ex){if(!silent)MessageBox.Show(ex.Message,"LilyTools Setup");else File.WriteAllText(Path.Combine(Path.GetTempPath(),"LilyTools-setup-error.txt"),ex.ToString());return 1;}}
}
